from pathlib import Path
import hashlib,json,os,stat
root=Path('/usr/local'); rows=[]
for path in sorted(root.rglob('*')):
    info=path.lstat(); row={'path':str(path.relative_to(root)),'mode':stat.S_IMODE(info.st_mode)}
    if stat.S_ISLNK(info.st_mode): row.update(kind='symlink',target=os.readlink(path))
    elif stat.S_ISDIR(info.st_mode): row.update(kind='directory')
    elif stat.S_ISREG(info.st_mode):
        h=hashlib.sha256()
        with path.open('rb') as handle:
            while chunk:=handle.read(1024*1024):h.update(chunk)
        row.update(kind='file',bytes=info.st_size,sha256=h.hexdigest())
    else: raise RuntimeError('unsupported runtime inode')
    rows.append(row)
print(json.dumps(rows,sort_keys=True,separators=(',',':')))
